 { 
 if ( statsPerProcess . ContainsKey ( gcData . ProcessID )) 
 { 
 var genCounts = statsPerProcess [ gcData . ProcessID ]. GenCounts ; 
 if ( gcData . Depth >= 0 && gcData . Depth < genCounts . Length ) 
 { 
